import status2 from "http-status";
var AuthController = class extends baseController {
  createUser = this.handle(async (req, res) => {
    const payload = req.body;
    const user = await auth_service_default.createdb(payload);
    sendResponse(res, { success: true, message: "user created successfully", status: status2.CREATED, data: user });
  });
  loginUser = this.handle(async (req, res) => {
    const payload = req.body;
    const { accessToken, refreshToken } = await auth_service_default.logindb(payload);
    res.cookie("accessToken", accessToken, {
      httpOnly: true,
      secure: false,
      sameSite: "none",
      maxAge: 1e3 * 60 * 60 * 24
      // 24 hour or 1 day
    });
    res.cookie("refreshToken", refreshToken, {
      httpOnly: true,
      secure: false,
      sameSite: "none",
      maxAge: 1e3 * 60 * 60 * 24 * 7
      // 24 hour or 7 day
    });
    sendResponse(res, { success: true, message: "user logged in successfully", status: status2.CREATED, data: { accessToken, refreshToken } });
  });
  meget = this.handle(async (req, res) => {
    const payload = req.user;
    const user = await auth_service_default.meDB(payload);
    sendResponse(res, { success: true, message: "user is found", status: status2.CREATED, data: user });
  });
};
